package com.cloudticket.comment.event;
import com.cloudticket.comment.persistence.mapper.CommentMapper; import com.fasterxml.jackson.databind.ObjectMapper; import java.util.Set; import org.springframework.beans.factory.annotation.Value; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component;
@Component public class CommentLikeCountPublisher { private final StringRedisTemplate redis; private final CommentMapper comments; private final KafkaTemplate<String,String> kafka; private final ObjectMapper json; private final String topic; public CommentLikeCountPublisher(StringRedisTemplate r,CommentMapper c,KafkaTemplate<String,String> k,ObjectMapper j,@Value("${cloudticket.comment.like-topic:comment-events}") String t){redis=r;comments=c;kafka=k;json=j;topic=t;}
 @Scheduled(fixedDelayString="${cloudticket.comment.like-poll-ms:1000}") public void publish(){Set<String> ids=redis.opsForZSet().range("comment:likes:dirty",0,49);if(ids==null)return;for(String id:ids){var row=comments.selectById(id);if(row==null){redis.opsForZSet().remove("comment:likes:dirty",id);continue;}try{String payload=json.writeValueAsString(java.util.Map.of("eventId",java.util.UUID.randomUUID().toString(),"commentId",id,"likeCount",Math.max(0,row.getLikeCount()==null?0:row.getLikeCount())));kafka.send(topic,id,payload);redis.opsForZSet().remove("comment:likes:dirty",id);}catch(Exception ignored){}}}
}
